          g("Complete o cálculo da espera exponencial dobrando a cada tentativa falha:", ["tentativa"], "Math.pow(2, tentativa) dobra o atraso a cada rodada.", "const esperaMs = baseMs * Math.pow(2, ____);"),
          o("Ordene o fluxo de uma operação resiliente com retry e backoff exponencial:", ["Tentar executar a requisição assíncrona ao serviço externo","Detectar falha de rede transitória e verificar se há orçamento de tentativas","Calcular o tempo de espera exponencial com jitter e aguardar com sleep()","Executar a próxima tentativa ou lançar erro definitivo caso exceda o limite"], "Tentativa inicial, detecção de falha, espera exponencial calculada e nova tentativa."),
          p("Associe o conceito de resiliência à sua função operacional:", [["Backoff exponencial","Aumento multiplicativo do intervalo entre tentativas consecutivas"],["Jitter aleatório","Ruído estocástico que impede picos sincronizados de reconexão"],["Falha transitória","Instabilidade efêmera de rede que se resolve espontaneamente"],["Limite de tentativas (maxRetries)","Controle de segurança que evita loops infinitos de repetição"]], "Retries com backoff transformam serviços vulneráveis em clientes altamente resilientes.")
